-- image_data is een data-URL voor <img src="...">.
-- Een gewone BLOB is maximaal 64 KB. Deze png-bestanden zijn groter, daarom MEDIUMBLOB.
-- Alleen fruit met een overeenkomend bestand in public/images/fruits krijgt data. De rest blijft NULL.
UPDATE fruits SET image_data = 'data:image/png;base64,' WHERE name = 'appel';
